text.value:
{
  "JsonResponse": {
    "name": "LatestSeriesNewsComponent",
    "comment": "Component to display a grid of latest series news articles with images, categories, titles, descriptions, and dates. The news data is provided via an Input property 'newsItems'. Each news item includes image, category, title, description, and date. The component also emits an event when the 'Toute l'actu séries' button is clicked.",
    "css": "div.container {
  padding: 16px;
  background-color: var(--ion-color-light-shade);
}

h2.title {
  font-weight: 900;
  font-size: 1.8rem;
  margin-bottom: 16px;
  text-align: center;
}

div.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}

article.news-card {
  background-color: var(--ion-color-light);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
  display: flex;
  flex-direction: column;
}

img.news-image {
  width: 100%;
  height: 160px;
  object-fit: cover;
  border-top-left-radius: 12px;
  border-top-right-radius: 12px;
}

div.content {
  padding: 12px 16px 16px 16px;
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

span.category {
  font-size: 0.75rem;
  color: var(--ion-color-medium-tint);
  background-color: var(--ion-color-light-tint);
  padding: 2px 8px;
  border-radius: 10px;
  width: fit-content;
  margin-bottom: 6px;
}

h3.title {
  font-weight: 700;
  font-size: 1rem;
  margin: 0 0 6px 0;
  line-height: 1.2;
}

p.description {
  font-size: 0.875rem;
  color: var(--ion-color-dark-tint);
  flex-grow: 1;
  margin: 0 0 8px 0;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
}

small.date {
  font-size: 0.7rem;
  color: var(--ion-color-medium-tint);
}

ion-button.show-more {
  --border-radius: 20px;
  display: block;
  margin: 24px auto 0 auto;
  --padding-top: 6px;
  --padding-bottom: 6px;
  --padding-start: 20px;
  --padding-end: 20px;
}
",
    "XHTML": "<div class="container">
  <h2 class="title">{{ this?.headerTitle }}</h2>
  <div class="grid">
    <ng-container *ngFor="let item of this.newsItems">
      <article class="news-card">
        <img class="news-image" [src]="item.imageUrl" [alt]="item.title" />
        <div class="content">
          <span class="category">{{ item.category }}</span>
          <h3 class="title">{{ item.title }}</h3>
          <p class="description">{{ item.description }}</p>
          <small class="date">{{ item.date }}</small>
        </div>
      </article>
    </ng-container>
  </div>
  <ion-button class="show-more" fill="outline" (click)="onShowMoreClick()">{{ this?.buttonLabel }}</ion-button>
</div>",
    "variables": {
      "headerTitle": {
        "type": "string",
        "description": "Title displayed above the news grid",
        "value": "Dernières news séries"
      },
      "newsItems": {
        "type": "Array<{imageUrl: string; category: string; title: string; description: string; date: string;}>",
        "description": "Array of news items to display, each containing image URL, category, title, description, and date",
        "value": [
          {
            "imageUrl": "https://example.com/image1.jpg",
            "category": "News - Séries à la TV",
            "title": "Demain nous appartient : Jack déjà prêt à tourner la page sur son histoire avec Rayane ?",
            "description": "Dans Demain nous appartient, Jack va faire une rencontre. Cela va-t-il lui permettre de mettre sa relation avec Rayane derrière lui ?",
            "date": "vendredi 20 juin 2025"
          },
          {
            "imageUrl": "https://example.com/image2.jpg",
            "category": "News - Séries à la TV",
            "title": "Tout pour la lumière : Joël a-t-il voulu faire taire Florence ? Un indice relance les soupçons",
            "description": "Victoria est persuadée que la chute de Florence n’était pas un accident. Entre carnet mystérieux, enregistrement disparu…",
            "date": "vendredi 20 juin 2025"
          }
        ]
      },
      "buttonLabel": {
        "type": "string",
        "description": "Label for the show more button",
        "value": "Toute l'actu séries"
      }
    },
    "emitters": [
      "showMore"
    ],
    "interfaces": {},
    "declarations": [
      "headerTitle: string = 'Dernières news séries';",
      "newsItems: {imageUrl: string; category: string; title: string; description: string; date: string;}[] = [];",
      "buttonLabel: string = "Toute l'actu séries";"
    ],
    "functions": {
      "onShowMoreClick": "onShowMoreClick(): void {
  this.showMore.emit();
}"
    },
    "constructor": "constructor() {}",
    "ngOnInit": "null",
    "ngOnDestroy": "null",
    "ngOnChanges": "null",
    "ngDoCheck": "null",
    "ngAfterContentInit": "null",
    "ngAfterContentChecked": "null",
    "ngAfterViewInit": "null",
    "ngAfterViewChecked": "null",
    "comp-imports": {
      "Component": "@angular/core",
      "Input": "@angular/core",
      "Output": "@angular/core",
      "EventEmitter": "@angular/core"
    },
    "module-imports": {
      "IonicModule": "@ionic/angular",
      "FormsModule": "@angular/forms"
    },
    "module-ngmodules": [
      "IonicModule",
      "FormsModule"
    ],
    "module-ngproviders": [],
    "explanation": "Created an Angular component that displays a grid of news items with images, categories, titles, descriptions, and dates. The data is passed in through Input properties. The component uses a simple div container and Ionic button with an event emitter for the show more button. Styling uses CSS grid and Ionic color variables for a clean layout."
  }
}
